def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    opp_c = 0
    opp_d = 0
    my_d = 0
    seen_d = 0
    d_to_d = 0
    rec_d = 0
    retaliated = False
    verified = False

    recent_start = n - 10
    if recent_start < 0:
        recent_start = 0

    for i in range(n):
        a, b = history[i]
        if a == 'D':
            my_d += 1
        if b == 'C':
            opp_c += 1
        else:
            opp_d += 1
            if i >= recent_start:
                rec_d += 1

    for i in range(n - 1):
        a, b = history[i]
        a2, b2 = history[i + 1]
        if a == 'D':
            seen_d += 1
            if b2 == 'D':
                d_to_d += 1
            if b == 'C':
                if b2 == 'D':
                    retaliated = True
                elif a2 == 'C' and b2 == 'C':
                    verified = True

    persistent_sucker = False
    if n >= 2:
        persistent_sucker = (
            history[-1] == ('C', 'D') and history[-2] == ('C', 'D')
        )

    if opp_c == 0:
        return 'D'

    if rec_d >= 7:
        return 'D'

    high_total = (opp_d >= 7 and opp_d * 4 >= n)

    if high_total:
        punisher = (
            retaliated and
            seen_d >= 3 and
            d_to_d * 10 >= seen_d * 6 and
            opp_d <= opp_c
        )
        if punisher and rec_d < 6 and not persistent_sucker:
            return 'C'
        return 'D'

    if retaliated:
        if rec_d >= 6 or persistent_sucker:
            return 'D'
        if opp_d > opp_c and opp_d >= 7:
            return 'D'
        return 'C'

    if verified and opp_c >= 2 * opp_d:
        return 'D'

    if my_d == 0 and n >= 65 and n < 98 and opp_c >= 3 * opp_d:
        return 'D'

    return 'C'
